examples.template:
MonarchAiPermissionScope(
    scopes = listOf(
        MonarchAiPermissionScopeItem({{scopes.0.app}}, MonarchAiAccessLevel.{{scopes.0.access|pascal}}, resources = {{scopes.0.resources}}),
        MonarchAiPermissionScopeItem({{scopes.1.app}}, MonarchAiAccessLevel.{{scopes.1.access|pascal}}, resources = {{scopes.1.resources}}),
        MonarchAiPermissionScopeItem({{scopes.2.app}}, MonarchAiAccessLevel.{{scopes.2.access|pascal}}),
        MonarchAiPermissionScopeItem({{scopes.3.app}}, MonarchAiAccessLevel.{{scopes.3.access|pascal}}),
    ),
    accessIcon = { level ->
        MonarchIcon(
            when (level) {
                MonarchAiAccessLevel.None -> SampleIcons.Lock
                MonarchAiAccessLevel.Read -> SampleIcons.Eye
                MonarchAiAccessLevel.Write -> SampleIcons.Pencil
            },
            contentDescription = null,
        )
    },
)

examples.code:
MonarchAiPermissionScope(
    scopes = listOf(
        MonarchAiPermissionScopeItem("Calendar", MonarchAiAccessLevel.Read, resources = "Your events only"),
        MonarchAiPermissionScopeItem("Documents", MonarchAiAccessLevel.Write, resources = "Shared projects"),
        MonarchAiPermissionScopeItem("Contacts", MonarchAiAccessLevel.Read),
        MonarchAiPermissionScopeItem("Billing", MonarchAiAccessLevel.None),
    ),
    accessIcon = { level ->
        MonarchIcon(
            when (level) {
                MonarchAiAccessLevel.None -> SampleIcons.Lock
                MonarchAiAccessLevel.Read -> SampleIcons.Eye
                MonarchAiAccessLevel.Write -> SampleIcons.Pencil
            },
            contentDescription = null,
        )
    },
)

examples.setup:
var scopes by remember {
    mutableStateOf(
        listOf(
            MonarchAiPermissionScopeItem("Calendar", MonarchAiAccessLevel.Read),
            MonarchAiPermissionScopeItem("Drive", MonarchAiAccessLevel.Write),
        ),
    )
}
